import tifffile as tf
import numpy as np
from cellpose import models
from skimage.measure import regionprops

model = models.CellposeModel(gpu=False, pretrained_model='/opt/cellpose_models/nucleitorch_0')
wells = ['A06', 'A11', 'A12', 'C12', 'D10', 'E05', 'G07', 'H12']
manuals = {'A06': 34, 'A11': 66, 'A12': 10, 'C12': 18, 'D10': 31, 'E05': 113, 'G07': 127, 'H12': 38}

for flow_th in [0.4, 0.6, 0.8]:
    for diam in [12.0, 14.0, 16.0]:
        counts = {}
        for w in wells:
            im = tf.imread(f'/task/input/images/{w}_ch1.tif').astype(np.float32)
            masks, flows, styles = model.eval(im, diameter=diam, channels=[0,0], flow_threshold=flow_th, cellprob_threshold=0.0)

            count = 0
            for r in regionprops(masks):
                coords = r.coords
                if np.any(coords[:, 0] == 319) or np.any(coords[:, 1] == 319):
                    continue
                is_cut = np.any(coords[:, 0] == 0) or np.any(coords[:, 1] == 0)
                if is_cut:
                    if r.major_axis_length < 6.5:
                        continue
                else:
                    if r.minor_axis_length < 6.5:
                        continue
                count += 1
            counts[w] = count

        diffs = [abs(counts[w] - manuals[w]) for w in wells]
        max_diffs = [max(3, int(np.round(manuals[w]*0.1))) for w in wells]
        passed = all(d <= m for d, m in zip(diffs, max_diffs))
        print(f'flow={flow_th}, diam={diam}: diffs={dict(zip(wells, diffs))}, pass={passed}')
        if passed:
            print('SUCCESS!')
            break
    if passed:
        break
