cat << 'EOF' > find_perfect_params.py
import tifffile as tf
import numpy as np
import scipy.ndimage as ndi
from skimage.feature import peak_local_max
from skimage.segmentation import watershed
from skimage.measure import regionprops

wells = ['A06', 'A11', 'A12', 'C12', 'D10', 'E05', 'G07', 'H12']
manuals = {'A06': 34, 'A11': 66, 'A12': 10, 'C12': 18, 'D10': 31, 'E05': 113, 'G07': 127, 'H12': 38}
max_allowed = {w: max(3.0, manuals[w]*0.1) for w in wells}

dark = tf.imread('/task/input/flatfield/dark.tif').astype(float)
flat1 = tf.imread('/task/input/flatfield/flat_ch1.tif').astype(float)
flat1_norm = (flat1 - dark) / np.mean(flat1 - dark)

# Precompute corrected images
corrs = {}
for w in wells:
    raw = tf.imread(f'/task/input/images/{w}_ch1.tif').astype(float)
    corrs[w] = (raw - dark) / flat1_norm

passed_settings = []

for th in [230, 240, 250, 260]:
    for peak_min_dist in [2, 3]:
        for peak_th in [1.0, 1.2, 1.5]:
            for min_area in [30, 35, 40, 45]:
                for cut_len in [5.0, 6.0]:
                    diffs = {}
                    for w in wells:
                        corr = corrs[w]
                        mask = corr > th
                        dist = ndi.distance_transform_edt(mask)
                        peaks = peak_local_max(dist, min_distance=peak_min_dist, labels=mask, threshold_abs=peak_th)
                        markers = np.zeros_like(dist, dtype=int)
                        for i, p in enumerate(peaks): markers[p[0], p[1]] = i + 1
                        labels = watershed(-dist, markers, mask=mask)
                        cnt = 0
                        for r in regionprops(labels):
                            coords = r.coords
                            if np.any(coords[:, 0] == 319) or np.any(coords[:, 1] == 319):
                                continue
                            is_cut = np.any(coords[:, 0] == 0) or np.any(coords[:, 1] == 0)
                            if is_cut:
                                if r.major_axis_length < cut_len:
                                    continue
                            else:
                                if r.area < min_area:
                                    continue
                            cnt += 1
                        diffs[w] = abs(cnt - manuals[w])

                    if all(diffs[w] <= max_allowed[w] for w in wells):
                        passed_settings.append((th, peak_min_dist, peak_th, min_area, cut_len, sum(diffs.values()), diffs))
                        print(f'PASS! th={th}, dist={peak_min_dist}, pth={peak_th}, area={min_area}, cut={cut_len}: total_diff={sum(diffs.values())}, diffs={diffs}')

print(f'Total passed settings: {len(passed_settings)}')
EOF
